use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression `e` under a variable store `store`.
/// If a variable is not found in the store, it is treated as -1.
pub fn eval(e: &Exp, store: &HashMap<String, i32>) -> i32 {
    match e {
        Exp::Const(n) => *n,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(l, r) => eval(l, store) + eval(r, store),
        Exp::Mult(l, r) => eval(l, store) * eval(r, store),
    }
}

/// Perform a single‐step, root‐only peephole optimization on `e`.
/// Does not recurse into subexpressions.
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(left, right) => {
            // Take ownership of the two operands
            let (l, r) = (*left, *right);
            match (l, r) {
                // 0 * X  or  X * 0  => 0
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),

                // 1 * X  => X
                (Exp::Const(1), expr) => expr,
                // X * 1  => X
                (expr, Exp::Const(1)) => expr,

                // Constant folding: a * b => Const(a*b)
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b),

                // Otherwise leave as a multiplication node
                (l, r) => Exp::Mult(Box::new(l), Box::new(r)),
            }
        }
        Exp::Plus(left, right) => {
            let (l, r) = (*left, *right);
            match (l, r) {
                // 0 + X  => X
                (Exp::Const(0), expr) => expr,
                // X + 0  => X
                (expr, Exp::Const(0)) => expr,

                // Constant folding: a + b => Const(a+b)
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b),

                // Otherwise leave as an addition node
                (l, r) => Exp::Plus(Box::new(l), Box::new(r)),
            }
        }
        // Constants and variables are unchanged
        other => other,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_eval_basics() {
        let mut store = HashMap::new();
        store.insert("x".to_string(), 4);
        store.insert("y".to_string(), 10);

        let expr = Exp::Plus(
            Box::new(Exp::Mult(
                Box::new(Exp::Var("x".to_string())),
                Box::new(Exp::Const(2)),
            )),
            Box::new(Exp::Var("y".to_string())),
        );
        // (x * 2) + y  with x=4, y=10  =>  8 + 10  = 18
        assert_eq!(eval(&expr, &store), 18);

        // Unbound var "z" yields -1
        let expr_z = Exp::Var("z".to_string());
        assert_eq!(eval(&expr_z, &store), -1);
    }

    #[test]
    fn test_optimize_mult() {
        // 0 * (anything)  => 0
        let e1 = Exp::Mult(Box::new(Exp::Const(0)), Box::new(Exp::Var("x".to_string())));
        assert_eq!(optimize(e1), Exp::Const(0));

        // 1 * x  => x
        let e2 = Exp::Mult(Box::new(Exp::Const(1)), Box::new(Exp::Var("x".to_string())));
        assert_eq!(optimize(e2), Exp::Var("x".to_string()));

        // 2 * 3  => 6
        let e3 = Exp::Mult(Box::new(Exp::Const(2)), Box::new(Exp::Const(3)));
        assert_eq!(optimize(e3), Exp::Const(6));

        // No rule applies: x * y stays as is
        let e4 = Exp::Mult(Box::new(Exp::Var("x".to_string())), Box::new(Exp::Var("y".to_string())));
        let o4 = optimize(e4.clone());
        assert_eq!(o4, e4);
    }

    #[test]
    fn test_optimize_plus() {
        // 0 + x  => x
        let e1 = Exp::Plus(Box::new(Exp::Const(0)), Box::new(Exp::Var("x".to_string())));
        assert_eq!(optimize(e1), Exp::Var("x".to_string()));

        // 2 + 3  => 5
        let e2 = Exp::Plus(Box::new(Exp::Const(2)), Box::new(Exp::Const(3)));
        assert_eq!(optimize(e2), Exp::Const(5));

        // No rule applies: x + y stays as is
        let e3 = Exp::Plus(Box::new(Exp::Var("x".to_string())), Box::new(Exp::Var("y".to_string())));
        let o3 = optimize(e3.clone());
        assert_eq!(o3, e3);
    }

    #[test]
    fn test_optimize_correctness_preserves_eval() {
        // For any expression and store, eval(e) == eval(optimize(e))
        let mut store = HashMap::new();
        store.insert("x".into(), 5);
        store.insert("y".into(), 0);

        let exprs = vec![
            Exp::Const(7),
            Exp::Var("x".into()),
            Exp::Var("z".into()),                // unbound var
            Exp::Plus(Box::new(Exp::Const(0)), Box::new(Exp::Var("x".into()))),
            Exp::Plus(Box::new(Exp::Const(2)), Box::new(Exp::Const(3))),
            Exp::Mult(Box::new(Exp::Const(1)), Box::new(Exp::Var("y".into()))),
            Exp::Mult(Box::new(Exp::Const(0)), Box::new(Exp::Var("x".into()))),
        ];

        for e in exprs {
            let v1 = eval(&e, &store);
            let v2 = eval(&optimize(e.clone()), &store);
            assert_eq!(v1, v2);
        }
    }
}